"""Presentation components derived only from the event's recorded plan."""
from html import escape

COLORS = ['#b9ed80', '#83d7ef', '#c1a4fa', '#ffca8a', '#ff9da9', '#80dfc2']

def enhancements(b, c, outputs, campaign):
    e = lambda v: escape(str(v), quote=True)
    topic_colors = {t['topic']: COLORS[i % len(COLORS)] for i, t in enumerate(c['topics'])}
    venue = b.get('venue') or 'Venue to be confirmed'
    ticket = '<aside class="event-ticket"><span>YOUR EVENT / AT A GLANCE</span><strong>'+e(b['city'])+'</strong><p>'+e(venue)+'</p><div class="ticket-rule"></div><div class="ticket-data"><b>'+e(b['startTime'])+'</b><span>DAILY START</span><b>'+e(b['duration'])+' min</b><span>PER DAY</span></div><div class="ticket-code" aria-hidden="true"></div><small>PLANNING DRAFT · DATE TBC</small></aside>'
    booths=[]
    for booth in c['booths']:
        visits=[r for r in c['schedule'] if r['booth']==booth['booth']]
        topics=list(dict.fromkeys(r['topic'] for r in visits))
        badges=''.join('<span style="--accent:'+topic_colors.get(t,COLORS[0])+'">'+e(t)+'</span>' for t in topics)
        booths.append('<article class="floor-booth"><div><b>'+e(booth['booth'])+'</b><small>'+str(len(visits))+' sessions</small></div>'+badges+'<p>'+e(booth['presenter'])+'</p></article>')
    floor='<section class="section" id="floor"><div class="sectionhead"><div class="section-number">02</div><div><small>THE SPACE</small><h2>Your experience floor</h2></div></div><p>A schematic of your booth assignments · not a venue floor plan.</p><div class="floor"><div class="floor-entry">WELCOME / CHECK-IN <span>→ EXPLORE THE BOOTHS</span></div><div class="floor-grid">'+''.join(booths)+'</div><div class="floor-exit">'+str(c['floorHosts'])+' floor hosts · '+str(c['presenterCount'])+' presenter slots · 1 event lead</div></div></section>'
    readiness = [('Event brief', '0' in outputs), ('Experience concepts', all(t.get('action') and t.get('outcome') for t in c['topics'])), ('Operations review', '2' in outputs), ('Invitation draft', bool(campaign))]
    progress='<div class="production"><span>YOUR CREW’S PROGRESS</span>'+''.join('<span class="'+('complete' if done else '')+'">'+('✓ ' if done else '○ ')+name+'</span>' for name,done in readiness)+'</div>'
    return ticket, floor, progress

